79	fn parse_utility_identifier(p: &mut CssParser) -> ParsedSyntax {
80	    if is_at_identifier(p) {
81	        parse_identifier(p, CssLexContext::Regular)
82	    } else if p.cur().is_known_dimension_unit() {
83	        let m = p.start();
84	        p.bump_remap(T![ident]);
85	        Present(m.complete(p, CSS_IDENTIFIER))
86	    } else {
87	        Absent
88	    }
89	}
90	
91	fn is_at_utility_identifier(p: &mut CssParser) -> bool {
92	    is_at_identifier(p) || p.cur().is_known_dimension_unit()
93	}
