157	
158	    let m = p.start();
159	
160	    p.bump(T!['(']);
161	    if p.at(T![@]) {
162	        parse_at_rule_declarator(p).ok();
163	    } else {
164	        let mut selector_list = SelectorList::default()
165	            .with_end_kind_ts(token_set![T![')']])
166	            .with_recovery_ts(token_set![T![')'], T![,], T![;]]);
