    }
    p.expect(T![')']);
    p.expect(T![;]);

    Present(m.complete(p, TW_CUSTOM_VARIANT_SHORTHAND))
}

// @apply text-lg font-bold;
pub(crate) fn parse_apply_at_rule(p: &mut CssParser) -> ParsedSyntax {
    if !p.at(T![apply]) {
        return Absent;
    }

